//! Shared benchmark configuration.

use serde::{Deserialize, Serialize};

pub(crate) const MAX_CONCURRENCY: usize = 64;
/// Serialized configuration bound shared by setup and every configuration reader.
pub(crate) const MAX_CONFIG_BYTES: usize = 64 * 1024;
/// Project-relative home for logs generated by ASB defaults.
///
/// Explicit `log_file` selections retain their location.  Keeping defaults in
/// one hidden directory lets a project root remain useful for source,
/// configuration, and report files.
pub(crate) const DEFAULT_LOG_DIRECTORY: &str = ".asb-logs";

/// Small, extensible benchmark configuration written by `asb setup`.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub struct BenchmarkConfig {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(crate) planning: Option<crate::planning::PlanningConfig>,
    pub agent: String,
    pub workload: String,
    pub provider: String,
    pub model: String,
    /// Number of identical agent executions to run concurrently.
    #[serde(
        default = "default_concurrency",
        deserialize_with = "deserialize_concurrency"
    )]
    pub concurrency: usize,
    /// Optional trial-set TOML selected for an external workload.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trial_set: Option<String>,
    /// Optional trial identifier within the selected trial set.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trial: Option<String>,
    #[serde(default = "default_workspace")]
    pub workspace: String,
    #[serde(default = "default_log_file")]
    pub log_file: String,
    #[serde(default)]
    pub measurements: Option<MeasurementConfig>,
}

/// Measurement modules selected by generated setup files.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub struct MeasurementConfig {
    pub enabled: bool,
    pub directory: String,
    pub collectors: Vec<String>,
}

fn default_workspace() -> String {
    "./asb-workspace".into()
}

pub(crate) fn default_log_path(name: &str) -> String {
    format!("{DEFAULT_LOG_DIRECTORY}/{name}")
}

fn default_log_file() -> String {
    default_log_path("benchmark.log")
}

fn default_concurrency() -> usize {
    1
}

fn deserialize_concurrency<'de, D>(deserializer: D) -> Result<usize, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let value = usize::deserialize(deserializer)?;
    if value == 0 {
        return Err(serde::de::Error::custom("concurrency must be at least 1"));
    }
    if value > MAX_CONCURRENCY {
        return Err(serde::de::Error::custom(format!(
            "concurrency must not exceed {MAX_CONCURRENCY}; split larger selections into bounded sweeps"
        )));
    }
    Ok(value)
}

#[cfg(test)]
mod tests {
    use super::{BenchmarkConfig, default_log_path};

    #[test]
    fn concurrency_defaults_to_one_and_accepts_positive_values() {
        let config: BenchmarkConfig = toml::from_str(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\n",
        )
        .expect("default configuration parses");
        assert_eq!(config.concurrency, 1);
        assert_eq!(config.log_file, ".asb-logs/benchmark.log");

        let config: BenchmarkConfig = toml::from_str(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\nconcurrency=3\n",
        )
        .expect("positive concurrency parses");
        assert_eq!(config.concurrency, 3);
    }

    #[test]
    fn zero_concurrency_is_rejected() {
        let error = toml::from_str::<BenchmarkConfig>(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\nconcurrency=0\n",
        )
        .expect_err("zero concurrency must be invalid");
        assert!(error.to_string().contains("concurrency must be at least 1"));
    }

    #[test]
    fn concurrency_is_bounded_before_replica_allocation() {
        for concurrency in [64u64, 65, u64::MAX] {
            let config = format!(
                "agent='pi'\nworkload='bug-fix'\nprovider='cli2key'\nmodel='fixture'\nconcurrency={concurrency}\n"
            );
            let parsed = toml::from_str::<BenchmarkConfig>(&config);
            if concurrency == 64 {
                assert_eq!(parsed.unwrap().concurrency, 64);
            } else {
                assert!(parsed.is_err());
            }
        }
    }

    #[test]
    fn default_logs_are_collected_under_the_hidden_log_directory() {
        assert_eq!(default_log_path("run.jsonl"), ".asb-logs/run.jsonl");
    }
}
